"""Dependency-free MVP web client embedded by the v2 service."""

INDEX_HTML = r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Research Trace v2</title>
<style>
:root{--bg:#f4f3ef;--paper:#fffefb;--ink:#23251f;--muted:#72766b;--line:#dedfd8;--accent:#376a52;--soft:#e7f0ea;--warn:#9a5d22;--danger:#9b3e43;--shadow:0 10px 32px rgba(35,37,31,.08)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Inter,ui-sans-serif,system-ui,"PingFang SC","Microsoft YaHei",sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}.top{height:58px;background:#20382e;color:#fff;display:flex;align-items:center;padding:0 24px;gap:18px;position:sticky;top:0;z-index:20}.brand{font-weight:750;letter-spacing:.02em}.top input{flex:1;max-width:650px;border:0;border-radius:9px;padding:9px 12px;background:rgba(255,255,255,.13);color:#fff}.top input::placeholder{color:#d7e2dc}.top button{border:1px solid rgba(255,255,255,.28);background:transparent;color:#fff;border-radius:8px;padding:7px 11px}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);min-height:calc(100vh - 58px)}aside{border-right:1px solid var(--line);padding:22px 16px;background:#eeeee9}.section-title{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);margin:0 7px 8px}.project,.chapter{width:100%;border:0;background:transparent;text-align:left;padding:9px 10px;border-radius:8px;color:var(--ink);margin:2px 0}.project:hover,.chapter:hover,.project.on,.chapter.on{background:var(--paper)}.project.on,.chapter.on{box-shadow:0 1px 0 var(--line)}.chapter .count{float:right;color:var(--muted)}.side-add{width:100%;margin:10px 0 24px;border:1px dashed #aeb3aa;background:transparent;padding:8px;border-radius:8px;color:var(--muted)}main{padding:30px clamp(20px,4vw,64px) 80px;max-width:1180px;width:100%;margin:auto}.empty{padding:80px 20px;text-align:center;color:var(--muted)}.hero{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:20px}.hero h1{font:700 clamp(28px,4vw,42px)/1.12 Georgia,"Songti SC",serif;margin:0 0 6px}.meta{color:var(--muted);font-size:13px}.card{background:var(--paper);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:22px;margin:0 0 18px}.card h2{font:700 21px/1.25 Georgia,"Songti SC",serif;margin:0 0 14px}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#fff;border-radius:8px;padding:7px 11px;color:var(--ink)}.btn.primary{background:var(--accent);border-color:var(--accent);color:white}.btn.warn{color:var(--warn)}.body{white-space:pre-wrap;overflow-wrap:anywhere}.editor textarea,.editor input{width:100%;border:1px solid var(--line);border-radius:9px;padding:10px;background:#fff;outline:none}.editor textarea{min-height:160px;resize:vertical}.editor label{display:block;color:var(--muted);font-size:12px;margin:10px 0 4px}.comments{border-top:1px solid var(--line);margin-top:18px;padding-top:14px}.comment{border-left:3px solid #b8bcb4;padding:8px 10px;margin:8px 0;background:#f8f8f4;border-radius:0 8px 8px 0}.comment.correction{border-left-color:var(--danger)}.comment.confirmation{border-left-color:var(--accent)}.comment .who{font-size:12px;color:var(--muted)}.comment.resolved{opacity:.55}.comment-form{display:grid;grid-template-columns:130px 1fr auto;gap:8px;margin-top:10px}.comment-form select,.comment-form input{border:1px solid var(--line);border-radius:8px;padding:8px;background:white}.chapter-head{display:flex;align-items:center;justify-content:space-between;gap:16px}.timeline{position:relative;margin-left:8px}.timeline:before{content:"";position:absolute;left:13px;top:8px;bottom:12px;width:1px;background:#cdd0c8}.node{position:relative;margin:0 0 14px;padding-left:40px}.node:before{content:"";position:absolute;left:7px;top:20px;width:13px;height:13px;border:3px solid var(--bg);background:var(--accent);border-radius:50%;box-shadow:0 0 0 1px #9daa9f}.node-card{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:17px 19px}.node-card h3{margin:0 0 5px;font-size:17px}.node-card .body{margin-top:11px}.pill{display:inline-block;border-radius:999px;padding:2px 8px;font-size:11px;background:var(--soft);color:var(--accent);margin:3px 4px 0 0}.pill.muted{background:#eee;color:var(--muted)}.code{margin-top:12px;border:1px solid #d9ddd6;border-radius:9px;overflow:hidden}.code-head{padding:7px 10px;background:#edf0eb;font:12px ui-monospace,monospace;color:#475249}.code pre{margin:0;padding:12px;overflow:auto;background:#19221d;color:#e9eee9;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.artifact{font-size:13px;margin:6px 0;padding:6px 9px;border-radius:7px;background:#f0f1ed}.raw-card summary{cursor:pointer;font-weight:700}.raw-list{margin-top:14px;border-top:1px solid var(--line)}.raw-row{padding:10px 0;border-bottom:1px solid var(--line)}.raw-row pre{white-space:pre-wrap;max-height:160px;overflow:auto;margin:5px 0 0;font:12px/1.45 ui-monospace,monospace;color:#42483f}.danger{color:var(--danger)}dialog{border:0;border-radius:14px;padding:0;max-width:620px;width:calc(100% - 32px);box-shadow:0 24px 70px rgba(0,0,0,.25)}dialog::backdrop{background:rgba(20,25,22,.42)}dialog form{padding:24px}.dialog-title{font:700 22px Georgia,serif;margin:0 0 12px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.search-results{position:fixed;top:53px;left:280px;right:40px;max-width:760px;z-index:30;background:white;border:1px solid var(--line);border-radius:0 0 12px 12px;box-shadow:var(--shadow);max-height:60vh;overflow:auto}.hit{padding:11px 14px;border-bottom:1px solid var(--line)}.hit:last-child{border:0}.hit small{color:var(--muted)}[hidden]{display:none!important}@media(max-width:760px){.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}main{padding:22px 14px 60px}.comment-form{grid-template-columns:1fr}.search-results{left:14px;right:14px}.grid2{grid-template-columns:1fr}}
</style>
</head>
<body>
<header class="top"><div class="brand">Research Trace</div><input id="search" placeholder="搜索项目记录与原始历史…"><button id="tokenBtn">连接设置</button></header>
<div id="searchResults" class="search-results" hidden></div>
<div class="layout"><aside><div class="section-title">Projects</div><div id="projects"></div><button class="side-add" id="addProject">＋ 新建项目</button><div id="chapterArea" hidden><div class="section-title">Chapters · 无先后顺序</div><div id="chapters"></div><button class="side-add" id="addChapter">＋ 新建 Chapter</button></div></aside><main id="main"><div class="empty">选择或新建一个项目</div></main></div>
<dialog id="modal"><form method="dialog" class="editor"><div class="dialog-title" id="modalTitle"></div><div id="modalBody"></div><div class="toolbar" style="justify-content:flex-end;margin-top:18px"><button class="btn" value="cancel">取消</button><button class="btn primary" id="modalSave" value="default">保存</button></div></form></dialog>
<script>
const S={projects:[],project:null,chapter:null,token:localStorage.getItem('trace.v2.token')||'',actor:localStorage.getItem('trace.v2.actor')||'human',authEnabled:false,user:null,csrf:''};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function headers(write=false){const h={'Content-Type':'application/json','X-Trace-Actor':S.actor};if(!S.authEnabled&&S.token)h.Authorization='Bearer '+S.token;if(write&&S.csrf)h['X-CSRF-Token']=S.csrf;return h}
async function api(path,opt={}){const r=await fetch(path,{...opt,headers:{...headers(opt.method&&opt.method!=='GET'),...(opt.headers||{})}});let v;try{v=await r.json()}catch{v={error:await r.text()}}if(r.status===401&&S.authEnabled){location.href='/auth/github/login?return_to='+encodeURIComponent(location.pathname+location.search);throw Error('登录已过期，正在重新登录')}if(!r.ok)throw Error(v.error||v.detail||r.statusText);return v}
function canWrite(){return !S.authEnabled||(S.user&&['member','admin'].includes(S.user.role))}
function fmt(t){if(!t)return'';try{return new Date(t).toLocaleString()}catch{return t}}
function file64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',',2)[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(file)})}
function setModal(title,html,onSave){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modalSave').onclick=async e=>{e.preventDefault();try{await onSave();$('#modal').close()}catch(err){alert(err.message)}};if(!$('#modal').open)$('#modal').showModal()}
async function loadProjects(){const v=await api('/api/v2/projects');S.projects=v.projects;renderSide();if(S.project){const found=S.projects.find(p=>p.id===S.project.id);if(!found){S.project=null;S.chapter=null;renderMain()}}}
function renderSide(){$('#projects').innerHTML=S.projects.map(p=>`<button class="project ${S.project&&S.project.id===p.id?'on':''}" data-project="${esc(p.id)}">${esc(p.name)}<span class="count">${p.node_count}</span></button>`).join('');$('#addProject').hidden=!canWrite();$('#chapterArea').hidden=!S.project;if(S.project){$('#chapters').innerHTML=S.project.chapters.map(c=>`<button class="chapter ${S.chapter&&S.chapter.id===c.id?'on':''}" data-chapter="${esc(c.id)}">${c.is_inbox?'⌁ ':''}${esc(c.name)}<span class="count">${S.project.nodes.filter(n=>n.chapter_id===c.id).length}</span></button>`).join('');$('#addChapter').hidden=!canWrite()}}
async function openProject(id){S.project=await api('/api/v2/projects/'+encodeURIComponent(id));S.chapter=null;renderSide();renderMain()}
function commentHtml(comments,targetType,targetId){return `<div class="comments"><div class="section-title" style="margin-left:0">Comments / Corrections</div>${comments.map(c=>`<div class="comment ${esc(c.kind)} ${c.resolved_at?'resolved':''}"><div>${esc(c.body)}</div><div class="who">${esc(c.kind)} · ${esc(c.author_id||c.author_type)} · ${fmt(c.created_at)} ${c.resolved_at?'· 已处理':''}</div></div>`).join('')}${canWrite()?`<div class="comment-form"><select data-comment-kind><option value="comment">评论</option><option value="correction">纠正</option><option value="confirmation">确认</option></select><input data-comment-body placeholder="直接评论或纠正上面的内容"><button class="btn" data-add-comment data-type="${targetType}" data-id="${esc(targetId)}">添加</button></div>`:''}</div>`}
function overview(){const p=S.project;const comments=p.comments.filter(c=>c.target_type==='overview');return `<section class="card"><div class="chapter-head"><h2>Overview</h2><div class="toolbar"><span class="meta">v${p.overview_version}</span>${canWrite()?'<button class="btn" id="editOverview">编辑当前认识</button>':''}</div></div><div class="body">${esc(p.overview||'尚未形成项目 Overview。')}</div>${commentHtml(comments,'overview',p.id)}</section>`}
function summary(c){const comments=S.project.comments.filter(x=>x.target_type==='chapter'&&x.target_id===c.id);return `<section class="card"><div class="chapter-head"><h2>${esc(c.name)}</h2><div class="toolbar"><span class="meta">summary v${c.summary_version}</span>${canWrite()?'<button class="btn" id="editSummary">编辑当前摘要</button><button class="btn primary" id="addNode">＋ 添加 Node</button>':''}</div></div><div class="body">${esc(c.summary||'这一章还没有当前摘要。')}</div>${commentHtml(comments,'chapter',c.id)}</section>`}
function nodeHtml(n){const comments=n.comments||[];const codes=(n.code_evidence||[]).map(x=>`<div class="code"><div class="code-head">${esc(x.file_path)}${x.symbol?' · '+esc(x.symbol):''}${x.commit_hash?' @ '+esc(x.commit_hash.slice(0,10)):''} · ${esc(x.attribution)}</div>${x.snippet?`<pre>${esc(x.snippet)}</pre>`:''}${x.diff?`<pre>${esc(x.diff)}</pre>`:''}${x.annotation?`<div style="padding:9px 11px">${esc(x.annotation)}</div>`:''}</div>`).join('');const arts=(n.attachments||[]).map(a=>`<div class="artifact"><b>${esc(a.direction)}</b> · ${a.object_path?`<a href="/api/v2/attachments/${encodeURIComponent(a.id)}/content">${esc(a.name)}</a>`:esc(a.name)} ${a.external_path?'· '+esc(a.machine||'')+':'+esc(a.external_path):''}${a.uri?'· '+esc(a.uri):''}</div>`).join('');return `<article class="node"><div class="node-card"><div class="meta">${fmt(n.occurred_at)}${n.parent_id?' · 延续 '+esc(n.parent_id):''}</div><div class="chapter-head"><h3>${esc(n.title)}</h3>${canWrite()?`<div class="toolbar"><button class="btn" data-edit-node="${esc(n.id)}">编辑</button><button class="btn" data-attach-node="${esc(n.id)}">附件 / 产物</button></div>`:''}</div><div>${(n.labels||[]).map(x=>`<span class="pill">${esc(x)}</span>`).join('')}<span class="pill muted">${esc(n.review_state)}</span></div><div class="body">${esc(n.body)}</div>${codes}${arts}${commentHtml(comments,'node',n.id)}</div></article>`}
function rawHistory(){return `<details class="card raw-card" id="rawHistory"><summary>原始 Session / Agent 历史 <span class="meta">按需加载，默认折叠</span></summary><div class="raw-list" id="rawItems"><div class="meta" style="padding-top:12px">展开后读取最近记录；完整内容仍可全文搜索。</div></div></details>`}
async function loadRaw(){const box=$('#rawItems');box.innerHTML='<div class="meta" style="padding-top:12px">加载中…</div>';try{const v=await api('/api/v2/projects/'+encodeURIComponent(S.project.id)+'/raw?limit=60');box.innerHTML=v.items.map(x=>`<div class="raw-row"><div><b>${esc(x.kind==='event'?x.event_type:'transcript')}</b> <span class="meta">${fmt(x.at)} · session ${esc(x.session_id||'—')} · agent ${esc(x.agent_id||'main')}</span></div><pre>${esc(x.kind==='event'?JSON.stringify(x.payload,null,2):x.preview)}</pre></div>`).join('')||'<div class="meta" style="padding-top:12px">还没有已上传的原始历史。</div>'}catch(err){box.innerHTML=`<div class="danger" style="padding-top:12px">${esc(err.message)}</div>`}}
function renderMain(){if(!S.project){$('#main').innerHTML='<div class="empty">选择或新建一个项目</div>';return}const p=S.project;const c=S.chapter;$('#main').innerHTML=`<div class="hero"><div><h1>${esc(p.name)}</h1><div class="meta">${p.node_count||p.nodes.length} 条语义记录 · 原始历史独立保存</div></div></div>${overview()}${rawHistory()}${c?summary(c)+`<div class="timeline">${p.nodes.filter(n=>n.chapter_id===c.id).map(nodeHtml).join('')||'<div class="empty">这个 Chapter 还没有 Node</div>'}</div>`:'<div class="empty">Chapter 之间没有时间顺序。选择一个 Chapter 查看其内部时间线。</div>'}`;bindMain();bindNodeActions()}
function bindMain(){const raw=$('#rawHistory');if(raw)raw.ontoggle=()=>{if(raw.open&&!raw.dataset.loaded){raw.dataset.loaded='1';loadRaw()}};const eo=$('#editOverview');if(eo)eo.onclick=()=>setModal('编辑 Overview',`<label>项目当前认识</label><textarea id="fieldBody">${esc(S.project.overview)}</textarea>`,async()=>{await api('/api/v2/curate',{method:'POST',body:JSON.stringify({project_id:S.project.id,target_type:'overview',body:$('#fieldBody').value,expect_version:S.project.overview_version,actor_type:'human'})});await openProject(S.project.id)});const es=$('#editSummary');if(es)es.onclick=()=>setModal('编辑 Chapter 摘要',`<label>当前摘要</label><textarea id="fieldBody">${esc(S.chapter.summary)}</textarea>`,async()=>{await api('/api/v2/curate',{method:'POST',body:JSON.stringify({project_id:S.project.id,target_type:'chapter',target_id:S.chapter.id,body:$('#fieldBody').value,expect_version:S.chapter.summary_version,actor_type:'human'})});const cid=S.chapter.id;await openProject(S.project.id);S.chapter=S.project.chapters.find(c=>c.id===cid);renderSide();renderMain()});const an=$('#addNode');if(an)an.onclick=()=>setModal('添加通用 Node',`<label>标题</label><input id="fieldTitle"><label>正文</label><textarea id="fieldBody"></textarea><div class="grid2"><div><label>发生时间（可空）</label><input id="fieldTime" type="datetime-local"></div><div><label>Labels（逗号分隔，可空）</label><input id="fieldLabels"></div></div><label>Parent Node ID（确实是延续时才填）</label><input id="fieldParent">`,async()=>{await api('/api/v2/record',{method:'POST',body:JSON.stringify({project_id:S.project.id,chapter_id:S.chapter.id,idempotency_key:'human-'+crypto.randomUUID(),title:$('#fieldTitle').value,body:$('#fieldBody').value,occurred_at:$('#fieldTime').value?new Date($('#fieldTime').value).toISOString():undefined,labels:$('#fieldLabels').value.split(',').map(x=>x.trim()).filter(Boolean),parent_id:$('#fieldParent').value||undefined,created_by:'human'})});const cid=S.chapter.id;await openProject(S.project.id);S.chapter=S.project.chapters.find(c=>c.id===cid);renderSide();renderMain()});document.querySelectorAll('[data-add-comment]').forEach(b=>b.onclick=async()=>{const box=b.closest('.comment-form');const body=box.querySelector('[data-comment-body]').value.trim();if(!body)return;await api('/api/v2/comments',{method:'POST',body:JSON.stringify({project_id:S.project.id,target_type:b.dataset.type,target_id:b.dataset.id,kind:box.querySelector('[data-comment-kind]').value,body})});const cid=S.chapter&&S.chapter.id;await openProject(S.project.id);if(cid)S.chapter=S.project.chapters.find(c=>c.id===cid);renderSide();renderMain()})}
function bindNodeActions(){document.querySelectorAll('[data-edit-node]').forEach(b=>b.onclick=()=>{const n=S.project.nodes.find(x=>x.id===b.dataset.editNode);setModal('编辑 Node',`<label>标题</label><input id="fieldTitle" value="${esc(n.title)}"><label>正文</label><textarea id="fieldBody">${esc(n.body)}</textarea><label>Labels（逗号分隔）</label><input id="fieldLabels" value="${esc((n.labels||[]).join(', '))}"><label>Parent Node ID（可空）</label><input id="fieldParent" value="${esc(n.parent_id||'')}">`,async()=>{await api('/api/v2/nodes/'+encodeURIComponent(n.id),{method:'PATCH',body:JSON.stringify({expect_version:n.version,actor_type:'human',patch:{title:$('#fieldTitle').value,body:$('#fieldBody').value,labels:$('#fieldLabels').value.split(',').map(x=>x.trim()).filter(Boolean),parent_id:$('#fieldParent').value||null}})});const cid=S.chapter.id;await openProject(S.project.id);S.chapter=S.project.chapters.find(x=>x.id===cid);renderSide();renderMain()})});document.querySelectorAll('[data-attach-node]').forEach(b=>b.onclick=()=>{const nodeId=b.dataset.attachNode;setModal('添加附件或外部产物',`<label>小文件（可空，服务默认上限 10 MB）</label><input id="fieldFile" type="file"><label>显示名称</label><input id="fieldArtifactName"><div class="grid2"><div><label>角色</label><select id="fieldDirection"><option value="reference">reference</option><option value="input">input</option><option value="output">output</option></select></div><div><label>机器（外部路径可填）</label><input id="fieldMachine"></div></div><label>外部路径（大数据/模型只登记位置）</label><input id="fieldExternal"><label>URI（可选）</label><input id="fieldUri">`,async()=>{const file=$('#fieldFile').files[0];const value={project_id:S.project.id,target_type:'node',target_id:nodeId,name:$('#fieldArtifactName').value||(file&&file.name)||'artifact',direction:$('#fieldDirection').value,machine:$('#fieldMachine').value||undefined,external_path:$('#fieldExternal').value||undefined,uri:$('#fieldUri').value||undefined};if(file){value.data_base64=await file64(file);value.mime_type=file.type||undefined;value.size=file.size}await api('/api/v2/attach',{method:'POST',body:JSON.stringify(value)});const cid=S.chapter.id;await openProject(S.project.id);S.chapter=S.project.chapters.find(x=>x.id===cid);renderSide();renderMain()})})}
$('#projects').onclick=e=>{const b=e.target.closest('[data-project]');if(b)openProject(b.dataset.project).catch(x=>alert(x.message))};$('#chapters').onclick=e=>{const b=e.target.closest('[data-chapter]');if(b){S.chapter=S.project.chapters.find(c=>c.id===b.dataset.chapter);renderSide();renderMain()}};
$('#addProject').onclick=()=>setModal('新建项目',`<label>项目名称</label><input id="fieldName"><label>Workspace key（可空，建议填 Git remote）</label><input id="fieldKey">`,async()=>{const p=await api('/api/v2/projects',{method:'POST',body:JSON.stringify({name:$('#fieldName').value,workspace_keys:$('#fieldKey').value?[ $('#fieldKey').value ]:[]})});await loadProjects();await openProject(p.id)});
$('#addChapter').onclick=()=>setModal('新建 Chapter',`<label>Chapter 名称</label><input id="fieldName"><label>当前摘要（可空）</label><textarea id="fieldBody"></textarea>`,async()=>{const c=await api(`/api/v2/projects/${encodeURIComponent(S.project.id)}/chapters`,{method:'POST',body:JSON.stringify({name:$('#fieldName').value,summary:$('#fieldBody').value})});await openProject(S.project.id);S.chapter=S.project.chapters.find(x=>x.id===c.id);renderSide();renderMain()});
async function showUsers(){const v=await api('/api/v2/admin/users');setModal('团队用户',v.users.map(u=>`<div class="card" style="padding:12px;margin:8px 0"><b>${esc(u.login)}</b> <span class="meta">${esc(u.display_name||'')} · GitHub #${esc(u.github_id)}</span><div class="toolbar" style="margin-top:8px"><select data-role="${esc(u.id)}"><option value="reader" ${u.role==='reader'?'selected':''}>reader</option><option value="member" ${u.role==='member'?'selected':''}>member</option><option value="admin" ${u.role==='admin'?'selected':''}>admin</option></select><label><input type="checkbox" data-disabled="${esc(u.id)}" ${u.disabled?'checked':''}> 禁用</label><button class="btn" data-save-user="${esc(u.id)}">保存</button></div></div>`).join('')||'<div class="meta">还没有用户</div>',async()=>{});document.querySelectorAll('[data-save-user]').forEach(b=>b.onclick=async e=>{e.preventDefault();const id=b.dataset.saveUser;try{await api('/api/v2/admin/users/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({role:document.querySelector(`[data-role="${id}"]`).value,disabled:document.querySelector(`[data-disabled="${id}"]`).checked})});await showUsers()}catch(err){alert(err.message)}})}
async function showDevices(){const v=await api('/api/v2/auth/devices');setModal('已登录设备',v.devices.map(d=>`<div class="card" style="padding:12px;margin:8px 0"><b>${esc(d.name)}</b><div class="meta">${d.revoked_at?'已撤销':'有效'} · 创建 ${fmt(d.created_at)} · 最近使用 ${fmt(d.last_used_at)||'尚未使用'}</div>${d.revoked_at?'':`<button class="btn warn" style="margin-top:8px" data-revoke-device="${esc(d.id)}">撤销</button>`}</div>`).join('')||'<div class="meta">还没有通过账号绑定的设备。</div>',async()=>{});document.querySelectorAll('[data-revoke-device]').forEach(b=>b.onclick=async e=>{e.preventDefault();if(!confirm('撤销这台设备？它的 Hook/MCP 将立即失效。'))return;try{await api('/api/v2/auth/devices/'+encodeURIComponent(b.dataset.revokeDevice),{method:'DELETE'});await showDevices()}catch(err){alert(err.message)}})}
$('#tokenBtn').onclick=()=>{if(S.authEnabled){setModal('账户',`<div><b>${esc(S.user.display_name||S.user.login)}</b></div><div class="meta">@${esc(S.user.login)} · ${esc(S.user.role)}</div><div class="toolbar" style="margin-top:16px"><button class="btn" id="manageDevices">管理已登录设备</button>${S.user.role==='admin'?'<button class="btn" id="manageUsers">管理团队用户</button>':''}<button class="btn warn" id="logoutBtn">退出登录</button></div>`,async()=>{});$('#manageDevices').onclick=e=>{e.preventDefault();showDevices().catch(err=>alert(err.message))};const m=$('#manageUsers');if(m)m.onclick=e=>{e.preventDefault();showUsers().catch(err=>alert(err.message))};$('#logoutBtn').onclick=async e=>{e.preventDefault();await api('/api/v2/auth/logout',{method:'POST'});location.reload()};return}setModal('连接设置',`<label>旧版写入 Token</label><input id="fieldToken" type="password" value="${esc(S.token)}"><label>你的显示名称</label><input id="fieldActor" value="${esc(S.actor)}"><div class="meta" style="margin-top:10px">推荐启用 GitHub OAuth 并使用 trace-v2-login；旧 Token 只保存在当前浏览器 localStorage。</div>`,async()=>{S.token=$('#fieldToken').value;S.actor=$('#fieldActor').value||'human';localStorage.setItem('trace.v2.token',S.token);localStorage.setItem('trace.v2.actor',S.actor)})};
let searchTimer;$('#search').oninput=e=>{clearTimeout(searchTimer);const q=e.target.value.trim();if(!q){$('#searchResults').hidden=true;return}searchTimer=setTimeout(async()=>{try{const v=await api('/api/v2/search?q='+encodeURIComponent(q)+'&scope=all&limit=30');$('#searchResults').innerHTML=v.hits.map(h=>`<div class="hit"><b>${esc(h.title||h.kind||h.event_type||h.scope)}</b><div>${esc(String(h.body||h.overview||'').slice(0,260))}</div><small>${esc(h.scope)} · ${fmt(h.occurred_at||h.captured_at||h.created_at||h.updated_at)}</small></div>`).join('')||'<div class="hit">没有结果</div>';$('#searchResults').hidden=false}catch(err){console.error(err)}},250)};document.addEventListener('click',e=>{if(!e.target.closest('.top')&&!e.target.closest('#searchResults'))$('#searchResults').hidden=true});
async function bootstrap(){const config=await api('/api/v2/auth/config');S.authEnabled=config.enabled;if(S.authEnabled){const r=await fetch('/api/v2/auth/me',{headers:{Accept:'application/json'}});if(!r.ok){$('#tokenBtn').textContent='GitHub 登录';$('#tokenBtn').onclick=()=>{location.href='/auth/github/login?return_to=/'};$('#main').innerHTML='<div class="empty"><h2>登录 Research Trace</h2><p>使用获准的 GitHub 账户访问团队研究记录。</p><a class="btn primary" href="/auth/github/login?return_to=/">使用 GitHub 登录</a></div>';$('#projects').innerHTML='';$('#addProject').hidden=true;return}const value=await r.json();S.user=value.user;S.csrf=value.csrf_token;S.actor=S.user.login;$('#tokenBtn').textContent='@'+S.user.login}await loadProjects()}
bootstrap().catch(err=>{$('#main').innerHTML=`<div class="empty danger">${esc(err.message)}</div>`});
</script>
</body></html>'''
